```APIDOC
## InjectQueue

### Description
Injects a BullMQ Queue instance registered with `BullModule.registerQueue()`. The decorator accepts an optional queue name and resolves the corresponding token.

### Signature
```ts
export const InjectQueue = (name?: string): ReturnType<typeof Inject> =>
  Inject(getQueueToken(name));
```

### Parameters
- `name` (string) - Optional - Queue name. Defaults to `'default'`. Resolves token `BullQueue_<name>` / `BullQueue_default`.

### Usage Example
```ts
import { Injectable } from '@nestjs/common';
import { InjectQueue } from '@nestjs/bullmq';
import { Queue } from 'bullmq';

@Injectable()
export class AudioService {
  constructor(@InjectQueue('audio') private readonly audioQueue: Queue) {}

  async add(file: string) {
    await this.audioQueue.add('transcode', { file });
  }
}
```
